steps.script:
const seen = new Set(); const rows = [];
const units = document.querySelectorAll('div[aria-posinset], div[role=feed] > div, div[role=article]:not(div[role=article] div[role=article])');
for (const u of units) {
  const msg = u.querySelector('[data-ad-preview=message], [data-ad-comet-preview=message], div[dir=auto][style*=text-align]');
  const text = (msg?.innerText || '').trim();
  if (!text || seen.has(text)) continue; seen.add(text);
  const author = u.querySelector('h2, h3, h4, strong')?.innerText?.trim() || '';
  const link = [...u.querySelectorAll('a[href]')].map(a => a.href).find(h => /\/posts\/|story_fbid|\/permalink|\/videos\/|\/reel\//.test(h)) || '';
  rows.push({ tac_gia: author, noi_dung: text, link: link.split('?')[0] || link });
}
return rows;
